using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Plain reference holder for the Versus card PREFAB (Assets/_Project/Prefabs/UI/VersusScreen.prefab,
/// UIPrefabLibrarySO.versusScreen, generated by Tools > MusicGame > UI > Build All UI Prefabs). Fully
/// static — VersusScreenController only fills the portraits/names, fades cardGroup and turns the backdrop
/// into a light veil (FightFlowConfig.versusBackdropAlpha); it never builds children.
/// </summary>
public class VersusScreenView : MonoBehaviour
{
    public GameObject root;
    [Tooltip("Faded by VersusScreenController (hold, then fade); never blocks raycasts.")]
    public CanvasGroup cardGroup;
    [Tooltip("Full-screen veil over the live arena; its alpha comes from FightFlowConfig.versusBackdropAlpha.")]
    public Image backdrop;

    [Header("Player (left)")]
    public Image           playerPortrait;
    public TextMeshProUGUI playerNameText;

    [Header("Center")]
    public TextMeshProUGUI vsText;

    [Header("Opponent (right)")]
    public Image           opponentPortrait;
    public TextMeshProUGUI opponentNameText;

    [Tooltip("Tint of a portrait slot with no sprite (no art yet).")]
    public Color placeholderPortraitColor = new(1f, 1f, 1f, 0.2f);
}
